public class IntelligentPromptRouterFactory(string resourceName = null, Action<Humidifier.Bedrock.IntelligentPromptRouter> factoryAction = null) : ResourceFactory<Humidifier.Bedrock.IntelligentPromptRouter>(resourceName)
{

    internal List<InnerIntelligentPromptRouterPromptRouterTargetModelFactory> ModelsFactories { get; set; } = [];

    internal InnerIntelligentPromptRouterPromptRouterTargetModelFactory FallbackModelFactory { get; set; }

    internal InnerIntelligentPromptRouterRoutingCriteriaFactory RoutingCriteriaFactory { get; set; }

    protected override Humidifier.Bedrock.IntelligentPromptRouter Create()
    {
        var intelligentPromptRouterResult = CreateIntelligentPromptRouter();
        factoryAction?.Invoke(intelligentPromptRouterResult);

        return intelligentPromptRouterResult;
    }

    private Humidifier.Bedrock.IntelligentPromptRouter CreateIntelligentPromptRouter()
    {
        var intelligentPromptRouterResult = new Humidifier.Bedrock.IntelligentPromptRouter
        {
            GivenName = InputResourceName,
        };

        return intelligentPromptRouterResult;
    }
    public override void CreateChildren(Humidifier.Bedrock.IntelligentPromptRouter result)
    {
        base.CreateChildren(result);

        result.Models = ModelsFactories.Any() ? ModelsFactories.Select(x => x.Build()).ToList() : null;
        result.FallbackModel ??= FallbackModelFactory?.Build();
        result.RoutingCriteria ??= RoutingCriteriaFactory?.Build();
    }

} // End Of Class

